import React from 'react'
import { Navigate, Outlet} from 'react-router-dom'
import PostScreen from '../Screen/PostScreen';

const PrivateRoute = () => {
    const auth = true; 
    return auth ? <Outlet /> : <Navigate to="/login" />;
}

export default PrivateRoute
